// @pit: {"label": "Apply fix in pit's durable tool and run repro test"}
async ({ shell: { exec }, workspace: { read, edit } }) => {
  const f = "/tmp/pit/src/durable/tool.ts";
  const r = await read(f, { format: "raw" });
  const a = `          onShellProgress: (event: ShellProgressEvent) => {
            executionProgress.recordShell(event);
            // Running output for the host's observers; the result replaces it.
            if (event.phase === "output") api.output(event.chunk);
          },`;
  if (!r.content.includes(a)) throw new Error("anchor");
  const b = `          onShellProgress: (event: ShellProgressEvent) => {
            executionProgress.recordShell(event);
            // Running output for the host's observers; the result replaces it.
            if (event.phase === "output" && shellOutputOpen) {
              try {
                api.output(event.chunk);
              } catch {
                // The call settled while a command still printed (its session failed, or the host aborted it), and
                // pi-durable takes no more output. The chunks left in the pipe have nowhere to go: a throw here
                // would escape the child's stdout handler and crash the host process.
                shellOutputOpen = false;
              }
            }
          },`;
  let c = r.content.replace(a, b);
  const decl = `      const handler = createNativeHostDispatcher(`;
  if (!c.includes(decl)) throw new Error("decl");
  c = c.replace(decl, `      let shellOutputOpen = true;\n` + decl);
  await edit(f, { revision: r.revision, changes: [{ kind: "replaceFile", content: c }] });
  // clean the test of debug output
  const tf = "/tmp/pit/test/durable/settled-output.test.ts";
  const t0 = await read(tf, { format: "raw" });
  let tc = t0.content.replace(/      const settled = await submission\.wait\(context\)[^\n]*\n      console\.log\("SETTLED"[^\n]*\n/, `      await expect(submission.wait(context)).rejects.toThrow("Session failed after a storage error");\n`);
  tc = tc.replace(`    console.log("ERRORS", errors.map(String));\n`, "");
  tc = tc.replace(`      // The command keeps printing for a while after the session failed.\n`, `      // The output still in the pipe arrives after the call settled.\n`);
  tc = tc.replace(`exec("touch started; yes tick")`, `exec("touch started; yes tick")`);
  await edit(tf, { revision: t0.revision, changes: [{ kind: "replaceFile", content: tc }] });
  const t = await exec(`cd /tmp/pit && for i in 1 2 3; do npx vitest run test/durable/settled-output.test.ts 2>&1 | sed 's/\\x1b\\[[0-9;]*m//g' | grep -E 'Tests |settled|Error' | cut -c1-200 | head -4; done; git stash -q -- src/durable/tool.ts && npx vitest run test/durable/settled-output.test.ts 2>&1 | sed 's/\\x1b\\[[0-9;]*m//g' | grep -E 'Tests ' ; git stash pop -q && git status --short`, { timeoutMs: 200000 });
  return t.stdout + t.stderr;
}
